    Game("prisoners-dilemma", "Prisoner's dilemma", "Social dilemmas", 1, "26-28", "Two players privately cooperate or defect; unilateral defection is tempting although mutual cooperation dominates mutual defection.", "sealed pair choice -> matrix payoff", "implemented", "prisoners-dilemma"),
    Game("linear-public-goods", "Linear voluntary-contribution public-good game", "Social dilemmas", 2, "112-21, 134-41", "Players allocate private tokens between themselves and a group account whose return is shared, creating a free-riding incentive.", "parallel contributions -> aggregate -> repeated feedback", "implemented", "public-goods"),
    Game("threshold-public-good", "Threshold / provision-point public good", "Social dilemmas", 2, "144-48", "The public return occurs only if total contributions reach a stated threshold; variants rebate contributions when provision fails.", "parallel contributions -> threshold -> rebate/payoff", "implemented", "threshold-public-good", "Aggregate provision is implemented; participant-wise rebates remain."),
    Game("commons-dilemma", "Commons dilemma", "Social dilemmas", 2, "126-30", "Members choose whether to conserve or exploit a shared resource; individual exploitation pays privately while imposing losses on the group.", "parallel binary choice -> congestion payoff", "implemented", "commons-dilemma", "Counting, thresholding, and mapped payoffs are implemented; durable resource stock remains."),
    Game("best-shot", "Best-shot public-good game", "Social dilemmas", 4, "279-81", "The group outcome is determined by the largest individual contribution rather than their sum, making one contributor sufficient for provision.", "parallel choices -> maximum -> payoffs", "implemented", "best-shot", "Maximum and identity-preserving participant payoff mapping are implemented."),
    Game("minimum-effort", "Minimum-effort coordination game", "Coordination", 3, "209-18", "Each player chooses effort from 1 to 7; payoff rises with the group's minimum effort but falls when one's effort exceeds that minimum.", "parallel effort -> minimum -> repeated payoff feedback", "implemented", "minimum-effort", "Minimum and identity-preserving participant payoff mapping are implemented."),
