    Game("chicken", "Chicken / hawk-dove", "Coordination", 2, "144-45", "Each player prefers standing firm when the other yields, but mutual aggression is worst for both.", "sealed pair choice -> matrix payoff", "implemented", "chicken", "Directly expressible with payoff_matrix."),
    Game("schelling-claims", "Schelling tacit claims game", "Coordination", 1, "12", "Two players independently claim shares of a fixed prize; claims are honored only when their sum does not exceed the prize.", "sealed claims -> feasibility test -> payoff", "implemented", "schelling-claims", "Fully expressible from sum, comparison, conditional, and mapped payoff."),
    Game("schelling-ranking", "Schelling tacit ranking game", "Coordination", 1, "12", "Three labeled players independently rank A, B, C; all earn rank-dependent prizes only if every ordering matches.", "parallel rankings -> all-equal -> rank payoff", "ready", "schelling-ranking", "Structured ranking equality is implemented; identity-specific rank prizes need list-position helpers."),
    Game("market-location", "Decentralized market-location coordination", "Coordination", 3, "233-44", "Players select locations with posted capacities; excess demand triggers random rationing, while exact allocation clears the market.", "changing cohorts -> location choices -> capacity lottery", pressure="Needs rematching, capacity constraints, and seeded lotteries."),

