    Game("unstructured-bargaining", "Unstructured bargaining", "Bargaining", 4, "255-56", "A pair negotiates a division with flexible messages until agreement or breakdown, allowing focal points and fairness norms to emerge.", "two-party conversation -> agreement/deadline", pressure="Needs conversational offers, counters, and agreement objects."),
    Game("alternating-offers", "Alternating-offer bargaining", "Bargaining", 4, "256-74", "Players alternate proposals over a shrinking or discounted pie; each response accepts or passes proposal rights to the opponent.", "bounded alternating loop -> accept or discount", pressure="Needs dynamic role swapping and a first-class agreement/termination hook."),
    Game("ultimatum", "Ultimatum game", "Bargaining", 4, "274-88, 296-302", "One player proposes a split and the responder accepts both payoffs or rejects and gives both zero.", "offer -> response -> conditional payoff", "implemented", "ultimatum"),
    Game("dictator", "Dictator game", "Bargaining", 4, "270, 298-302", "One player unilaterally chooses a transfer to a passive recipient, separating generosity from fear of rejection.", "allocation -> private payoff notices", "implemented", "dictator"),
    Game("impunity", "Impunity game", "Bargaining", 4, "300", "A responder can reject an allocation but rejection harms only the responder, leaving the allocator's payoff intact.", "offer -> response -> asymmetric conditional payoff", "implemented", "impunity", "Expressible with choose; warrants a reusable settlement object."),
    Game("optional-breakdown", "Optional-breakdown bargaining", "Bargaining", 4, "271-74", "After disagreement, either player may end bargaining for outside-option payments or continue with a discounted pie.", "alternating offers -> bilateral continue/quit -> discount", pressure="Needs joint continuation decisions and dynamic round state."),
