    Game("deadline-bargaining", "Deadline bargaining", "Bargaining", 4, "323-27", "Negotiation occurs under known or asymmetric deadlines, making delay and last-moment agreement strategically meaningful.", "conversation -> timers -> agreement/expiration", pressure="Needs wall-clock deadlines and race-safe late submissions."),

