    Game("monopoly", "Experimental monopoly", "Industrial organization", 5, "377-83", "A single seller chooses price or quantity against induced demand, sometimes under alternative regulatory rules.", "seller decision -> demand allocation -> profit/regulation", "implemented", "monopoly", "A serialized lookup implements discrete demand and profit settlement."),
    Game("contestable-market", "Potential-entry / contestable market", "Industrial organization", 5, "383-87", "An incumbent prices while potential entrants decide whether fixed costs and post-entry competition justify entry.", "incumbent action -> entry decisions -> market payoff", "implemented", "market-entry", "Current example simplifies incumbent pricing and entry costs."),
    Game("predatory-pricing", "Predatory-pricing game", "Industrial organization", 5, "387-91", "An incumbent may sacrifice current profit to deter an entrant who is uncertain about the incumbent's type or resolve.", "private incumbent type -> entry -> pricing -> repeated beliefs", pressure="Needs private types, repetition, and belief/history views."),
    Game("oligopoly-collusion", "Repeated oligopoly / collusion", "Industrial organization", 5, "398-416", "Firms repeatedly choose prices or quantities, possibly communicate, punish deviations, or use facilitating contractual terms.", "repeated firm choices -> market payoff -> history", pressure="Repeat exists; market clearing and communication policy remain."),
    Game("lemons-quality", "Endogenous-quality lemons market", "Industrial organization", 5, "417-19, 550-57", "Privately informed sellers choose quality or offers while buyers infer value, allowing adverse selection to collapse trade or quality.", "private quality -> offer -> buyer inference -> trade", pressure="Needs private types, quality-linked values, and transactions."),
