    Game("curse-of-knowledge", "Curse-of-knowledge information task", "Individual decisions", 8, "612-15", "Informed participants predict judgments of less-informed participants and often fail to disregard their own information.", "baseline response -> private reveal -> prediction of baseline", "implemented", "curse-of-knowledge", "Asymmetric staged information and deterministic comparison are implemented."),
    Game("allais", "Allais common-consequence choice", "Individual decisions", 8, "619-43", "Participants make paired lottery choices designed so common-consequence behavior can violate expected-utility independence.", "paired lottery choices -> consistency classification", "implemented", "allais", "Classification is implemented; typed lotteries and incentive-compatible random selection remain."),
    Game("ellsberg", "Ellsberg ambiguity task", "Individual decisions", 8, "644-49", "Participants choose between bets with known probabilities and bets whose probability is deliberately ambiguous.", "paired known/ambiguous lottery choices -> pattern classification", "implemented", "ellsberg", "Classification is implemented; typed urns, ambiguity, and random resolution remain."),
    Game("preference-reversal", "Preference-reversal task", "Individual decisions", 8, "657-65", "Participants both choose between lotteries and price them; the preferred lottery is often assigned the lower selling price.", "choice elicitation -> valuation elicitation -> reversal test", "implemented", "preference-reversal", "Linked classification is implemented; BDM valuation and random payment selection remain."),
    Game("bdm", "Becker-DeGroot-Marschak valuation", "Individual decisions", 1, "79-80", "A participant states a reservation value, a random price is drawn, and trade occurs only when the stated value crosses that price.", "valuation -> seeded random price -> conditional trade", "implemented", "bdm-valuation", "Stable numeric draws and conditional settlement are implemented; typed money remains."),
