    Game("search-task", "Sequential search task", "Individual decisions", 8, "670-73", "Participants pay to sample wage, price, or information offers and decide when to stop searching and accept.", "draw offer -> accept or pay to continue -> terminal choice", "implemented", "sequential-search", "Seeded offers, conditional stopping, search costs, and lazy terminal settlement are implemented."),
