def render(output: Path) -> Path:
    output = output.resolve()
    families = []
    for game in GAMES:
        if game.family not in families:
            families.append(game.family)
    counts = {status: sum(game.status == status for game in GAMES) for status in {g.status for g in GAMES}}
    nav = "".join(f'<a href="#{escape(f.lower().replace(" ", "-"))}">{escape(f)}</a>' for f in families)
    sections = []
    for family in families:
        cards = []
        for game in (item for item in GAMES if item.family == family):
            link = f'<a class="case" href="workflow_stress_gallery.html#{escape(game.existing_case)}">gallery case</a>' if game.existing_case else ""
            cards.append(f'''<article><div class="meta"><span class="status {game.status}">{escape(game.status)}</span><span>Chapter {game.chapter}, pp. {escape(game.pages)}</span>{link}</div><h3>{escape(game.name)}</h3><p>{escape(game.description)}</p><dl><dt>Workflow</dt><dd>{escape(game.workflow_shape)}</dd><dt>DSL pressure</dt><dd>{escape(game.pressure or "No major gap identified.")}</dd></dl></article>''')
        ident = family.lower().replace(" ", "-")
        sections.append(f'<section id="{escape(ident)}"><h2>{escape(family)}</h2><div class="grid">{"".join(cards)}</div></section>')
    payload = json.dumps([asdict(game) for game in GAMES], indent=2)
    output.write_text(f'''<!doctype html><html><head><meta charset="utf-8"><title>Handbook experimental-game catalog</title><style>html{{scroll-behavior:smooth}}body{{margin:0;background:#f2f4f7;color:#172033;font:14px/1.5 system-ui,sans-serif}}header,main{{max-width:1400px;margin:auto;padding:30px}}header{{padding-bottom:12px}}h1{{margin-bottom:6px}}header p{{max-width:900px;color:#586477}}nav{{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0}}nav a,.case{{color:#5b21b6;text-decoration:none}}nav a{{padding:7px 10px;background:white;border:1px solid #d8dee8;border-radius:8px}}.summary{{display:flex;gap:12px;flex-wrap:wrap}}.summary b{{background:#172033;color:white;padding:7px 11px;border-radius:8px}}section{{scroll-margin-top:15px;margin-bottom:36px}}h2{{border-bottom:2px solid #d8dee8;padding-bottom:8px}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:14px}}article{{background:white;border:1px solid #d8dee8;border-radius:12px;padding:18px;box-shadow:0 3px 10px #1720330b}}article h3{{margin:10px 0 5px}}article p{{color:#465267;min-height:62px}}.meta{{display:flex;gap:10px;align-items:center;color:#68758a;font-size:11px}}.status{{font-weight:800;text-transform:uppercase;padding:2px 7px;border-radius:10px}}.implemented{{background:#d1fae5;color:#065f46}}.ready{{background:#dbeafe;color:#1e40af}}.queued{{background:#ede9fe;color:#5b21b6}}dl{{display:grid;grid-template-columns:82px 1fr;gap:5px 8px;margin-bottom:0}}dt{{font-weight:750;color:#68758a}}dd{{margin:0}}details{{max-width:1400px;margin:0 auto 40px;background:#111827;color:#d1d5db;padding:14px;border-radius:10px}}pre{{overflow:auto;font-size:11px}}</style></head><body><header><h1>Experimental game catalog</h1><p>{len(GAMES)} reproducible mechanism families extracted and paraphrased from <em>The Handbook of Experimental Economics</em> (Kagel &amp; Roth, 1995). Printed-page references identify the source discussion. “Implemented” links to an existing workflow; “ready” fits current primitives; “queued” exposes additional language needs.</p><div class="summary">{"".join(f"<b>{counts.get(s, 0)} {s}</b>" for s in ("implemented", "ready", "queued"))}</div><nav>{nav}</nav></header><main>{''.join(sections)}</main><details><summary>Machine-readable catalog JSON</summary><pre>{escape(payload)}</pre></details></body></html>''', encoding="utf-8")
    return output


if __name__ == "__main__":
    print(render(Path(__file__).with_suffix(".html")))
